export const BODY: string = "\n<p>آپ کے پاس ایک تصویر ہے اور ایک فارم ہے جو 50KB سے اوپر کچھ بھی قبول نہیں کرتا۔ مرحلے معلوم ہوں تو یہ اصلاح تقریباً دو منٹ میں ہو جاتی ہے۔</p>\n<p>یہ رہنما پورا طریقہ بتاتا ہے۔ آپ درست ماخذ فائل تیار کریں گے، اسے کمپریسر سے گزاریں گے، نتیجہ جانچیں گے اور وہ عام مسائل ٹھیک کریں گے جن میں لوگ رک جاتے ہیں۔</p>\n<p>سافٹ ویئر انسٹال کرنے کی ضرورت نہیں ہے۔ نیچے سب کچھ عام براؤزر میں کام کرتا ہے، لیپ ٹاپ پر بھی اور فون پر بھی۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: درست ماخذ فائل لیں</h2>\n<p>اپنے پاس موجود بہترین اصل سے شروع کریں۔ کیمرے سے سیدھی تصویر اس کاپی سے کہیں بہتر کمپریس ہوتی ہے جو پہلے ہی ایک بار چھوٹی کی جا چکی ہو۔</p>\n<p>اگر تصویر چیٹ ایپ سے آئی ہے تو وہ پہلے سے کمپریس ہو سکتی ہے۔ اگر نتیجہ کھردرا لگے تو بھیجنے والے سے اصل فائل مانگیں۔</p>\n<p>کمپریس کرنے سے پہلے پورٹل کے اصول جانچیں۔ زیادہ سے زیادہ فائل سائز، مطلوبہ پکسل ابعاد اور قبول شدہ فارمیٹ نوٹ کریں۔</p>\n<h2 id=\"step-1-open-the-tool\">مرحلہ 1: 50KB کمپریسر کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/tasveer-compress-karein-50kb-tak/\">Compress Image to 50KB ٹول</a> کھولیں۔ صفحہ کمپریسر لوڈ کرتا ہے، اور آپ کی فائلیں آپ کے آلے پر رہتی ہیں۔</p>\n<p>آپ کو اکاؤنٹ کی ضرورت نہیں ہے۔ سائن اپ کا کوئی مرحلہ نہیں ہے اور کوئی اپ لوڈ قطار نہیں ہے، اس لیے آپ فوراً شروع کر سکتے ہیں۔</p>\n<p>اگر آپ فون پر ہیں تو وہی براؤزر استعمال کریں جو آپ عام طور پر استعمال کرتے ہیں۔ اپ لوڈ بٹن آپ کی فوٹو گیلری سیدھا کھول دیتا ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی تصویر اپ لوڈ کریں</h2>\n<p>اپنی تصویر اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل چننے کے لیے بٹن پر ٹیپ کریں۔ JPG، PNG، WebP اور HEIC فائلیں قبول ہوتی ہیں، ہر ایک 25 MB تک۔</p>\n<p>پاسپورٹ تصویر کے لیے مکمل ریزولوشن والا اصل اپ لوڈ کریں۔ ٹول چھوٹا کرنا سنبھال لیتا ہے، آپ کو پہلے ری سائز کرنے کی ضرورت نہیں ہے۔</p>\n<p>اسکین شدہ دستخط کے لیے سب سے صاف اسکین اپ لوڈ کریں۔ سفید پس منظر والا اسکین اس کاغذ کی تصویر سے کہیں بہتر کمپریس ہوتا ہے جو زاویے سے لی گئی ہو۔</p>\n<h2 id=\"step-3-let-it-search\">مرحلہ 3: ٹول کو بہترین کوالٹی ڈھونڈنے دیں</h2>\n<p>آپ کی تصویر لوڈ ہوتے ہی ٹول بائنری کوالٹی تلاش چلاتا ہے۔ یہ کوالٹی سطحیں آزماتا ہے جب تک وہ سب سے اونچی سطح نہ مل جائے جو اب بھی 50KB سے نیچے آئے۔</p>\n<p>آپ کو خود کوالٹی عدد چننے کی ضرورت نہیں ہے۔ تلاش اسی لیے ہے تاکہ آپ کو اندازہ نہ لگانا پڑے۔</p>\n<p>نتیجے پر Under 50KB بیج دیکھیں۔ یہ بیج بتاتا ہے کہ فائل حد پاس کر گئی ہے اور جمع کرانے کے لیے محفوظ ہے۔</p>\n<h2 id=\"step-4-preview\">مرحلہ 4: ڈاؤن لوڈ سے پہلے پیش نظارہ دیکھیں</h2>\n<p>ڈاؤن لوڈ سے پہلے کمپریس شدہ تصویر کا پیش نظارہ ہمیشہ دیکھیں۔ فائل سائز درست ہو سکتا ہے جبکہ تصویر خود خراب ہو۔</p>\n<p>اہم حصوں پر زوم کریں۔ پورٹریٹ میں آنکھیں اور چہرے کا خاکہ جانچیں۔ دستاویز میں سب سے چھوٹا متن جانچیں۔</p>\n<p>اگر ٹول موازنے کا منظر دے تو نتیجہ اصل کے ساتھ ساتھ دیکھیں۔ چھوٹے فرق معمول ہیں، ناقابل پڑھ متن نہیں۔</p>\n<h2 id=\"step-5-download\">مرحلہ 5: ڈاؤن لوڈ کریں اور فائل کا صاف نام رکھیں</h2>\n<p>کمپریس شدہ فائل ڈاؤن لوڈ کریں اور اسے صاف نام دیں۔ passport-photo-50kb.jpg جیسا نام مہینوں بعد بھی بالکل بتا دیتا ہے کہ یہ کیا ہے۔</p>\n<p>اصل فائل بھی رکھیں۔ اگر پورٹل کمپریس شدہ کاپی مسترد کر دے تو آپ ماخذ ڈھونڈے بغیر دوبارہ آزما سکتے ہیں۔</p>\n<p>اپنے آلے پر ڈاؤن لوڈ شدہ فائل کا سائز جانچیں۔ یہ 50KB سے تھوڑا نیچے پڑھنا چاہیے، عام طور پر 48KB سے 49.9KB کے درمیان۔</p>\n<h2 id=\"fixing-a-missed-target\">جب ہدف چھوٹ جائے تو اصلاح</h2>\n<p>ہدف چھوٹنے کی عام طور پر تین وجوہات میں سے ایک ہوتی ہے۔ فارمیٹ غلط ہے، ابعاد بند ہیں یا ماخذ غیر معمولی تفصیلی ہے۔</p>\n<p>پہلے آؤٹ پٹ فارمیٹ JPG کریں۔ PNG فارمیٹ میں تصویریں اکثر 50KB تک بالکل نہیں پہنچ سکتیں، چاہے آپ انہیں کتنا ہی چھوٹا کریں۔</p>\n<p>دوسرے، ابعاد اسکیلنگ کی اجازت دیں۔ ٹول پکسل سائز قدم بہ قدم کم کرتا ہے، اور چھوٹی کمی اکثر ہدف کھول دیتی ہے۔</p>\n<h2 id=\"passport-photo-tips\">پاسپورٹ اور شناختی تصویروں کے لیے نکات</h2>\n<p>پاسپورٹ پورٹل اکثر فائل سائز کے ساتھ بالکل ابعاد بھی مانگتے ہیں۔ ایک عام جوڑا 600 بہ 600 پکسل، 50KB سے نیچے ہے۔</p>\n<p>ایسی تصویر سے شروع کریں جو مطلوبہ شکل کے قریب ہو۔ چوڑے منظر کو مربع میں کراپ کرنے سے تصویر کا زیادہ تر حصہ ضائع ہو جاتا ہے۔</p>\n<p>سادہ، ہلکا پس منظر استعمال کریں۔ مصروف پس منظر تفصیل جوڑتا ہے جو کلو بائٹ کھاتا ہے اور چہرے سے توجہ ہٹاتا ہے۔</p>\n<h2 id=\"signature-scan-tips\">دستخط اور اسکین شدہ دستاویزات کے لیے نکات</h2>\n<p>دستخط خوبصورتی سے کمپریس ہوتے ہیں کیونکہ وہ زیادہ تر سفید جگہ ہوتے ہیں۔ صاف اسکین کوالٹی بچا کر 50KB تک پہنچ سکتا ہے۔</p>\n<p>معقول ریزولوشن پر اسکین کریں۔ 300 DPI اسکین کافی ہے، 1200 DPI اسکین صرف بڑی فائل بناتا ہے جسے سخت چھوٹا کرنا پڑتا ہے۔</p>\n<p>اپ لوڈ سے پہلے اسکین سیدھا کریں۔ ٹیڑھا دستخط خالی کونوں پر پکسل ضائع کرتا ہے جو کچھ نہیں جوڑتے۔</p>\n<h2 id=\"phone-workflow\">سب کچھ فون پر کرنا</h2>\n<p>فارم کے لیے تصویر کمپریس کرنے والے زیادہ تر لوگ فون پر ہوتے ہیں۔ ورک فلو وہی ہے، چند چھوٹے فرق کے ساتھ۔</p>\n<p>گیلری سے اصل تصویر چنیں، چیٹ ایپ سے محفوظ شدہ کاپی نہیں۔ چیٹ ایپس تصویریں آپ کے دیکھنے سے پہلے چھوٹی کر دیتی ہیں۔</p>\n<p>آئی فون پر تصویریں HEIC فائلیں ہو سکتی ہیں۔ ٹول HEIC قبول کرتا ہے، اس لیے اسے سیدھا اپ لوڈ کریں، پہلے بدلنے کی بجائے۔</p>\n<h2 id=\"checking-your-result\">اپنا نتیجہ درست طریقے سے کیسے جانچیں</h2>\n<p>ڈاؤن لوڈ شدہ فائل کھولیں اور اسے مکمل سائز میں دیکھیں۔ تھمب نیل وہ مسائل چھپاتا ہے جو پورٹل جائزہ لینے والا دیکھے گا۔</p>\n<p>تصویر میں کوئی بھی متن زور سے پڑھیں۔ اگر ہر لفظ پڑھ سکیں تو کمپریشن نے اپنا کام کر دیا۔</p>\n<p>فائل پورٹل پر اپ لوڈ کریں اور اس کی اپنی تصدیق دیکھیں۔ کچھ پورٹل پیش نظارہ دکھاتے ہیں، اسے تصویر درست دکھائی دینے کی تصدیق کے لیے استعمال کریں۔</p>\n<h2 id=\"choosing-dimensions\">کمپریس کرنے سے پہلے ابعاد چننا</h2>\n<p>ابعاد اور فائل سائز جڑے ہوئے ہیں۔ چھوٹی تصویر کو کم ڈیٹا چاہیے ہوتا ہے، اس لیے وہ کم کوالٹی نقصان کے ساتھ 50KB تک پہنچتی ہے۔</p>\n<p>جانچیں کہ آپ کا پورٹل ابعاد طے کرتا ہے یا نہیں۔ اگر کرتا ہے تو یہ فیصلہ آپ کے لیے ہو چکا ہے، اور آپ کو اس سے لڑنا نہیں چاہیے۔</p>\n<p>اگر ابعاد آزاد ہیں تو سب سے چھوٹا سائز ہدف بنائیں جو اپنے دکھائی دینے والے سائز پر اب بھی اچھا لگے۔ 300 پکسل چوڑی دکھائی دینے والی تصویر کو 2000 پکسل چوڑی ہونے کی ضرورت نہیں ہے۔</p>\n<h2 id=\"scanned-documents\">اسکین شدہ دستاویزات کو 50KB تک کمپریس کرنا</h2>\n<p>اسکین شدہ دستاویزات تصویروں سے مختلف برتاؤ کرتی ہیں۔ وہ زیادہ تر سفید جگہ ہوتی ہیں جن میں گہرا متن ہوتا ہے، جو بہت مؤثر انداز میں کمپریس ہوتا ہے۔</p>\n<p>جب رنگ کی ضرورت نہ ہو تو سرمئی اسکین کریں۔ سرمئی اسکین رنگ ڈیٹا کا تیسرا حصہ رکھتا ہے اور آسانی سے 50KB تک پہنچتا ہے۔</p>\n<p>کمپریس کرنے سے پہلے اسکین صاف کریں۔ دھول کے دھبے اور سائے شور جوڑتے ہیں جو کچھ بھی نہیں، اس پر کلو بائٹ ضائع کرتے ہیں۔</p>\n<h2 id=\"heic-photos\">آئی فون کی HEIC تصویروں کے ساتھ کام کرنا</h2>\n<p>آئی فون پہلے سے طے شدہ طور پر تصویریں HEIC میں محفوظ کرتے ہیں۔ یہ فائلیں پہلے سے اچھی کمپریس ہوتی ہیں، جس سے 50KB تک پہنچنا مشکل ہو سکتا ہے۔</p>\n<p>HEIC فائل سیدھا ٹول پر اپ لوڈ کریں۔ یہ HEIC پڑھتا ہے اور کمپریشن کے دوران بدلتا ہے، اس لیے الگ تبدیلی کا مرحلہ نہیں چاہیے۔</p>\n<p>پہلے کسی اور ایپ میں HEIC کو JPG میں بدلنا عام طور پر ضائع ہے۔ یہ اصل کمپریشن شروع ہونے سے پہلے نقصان والا مرحلہ جوڑ دیتا ہے۔</p>\n<h2 id=\"batch-50kb\">ایک ساتھ کئی فائلیں 50KB تک کمپریس کرنا</h2>\n<p>کئی فارموں کو دو فائلیں چاہییں ہوتی ہیں: ایک تصویر اور ایک دستخط۔ انہیں ساتھ کمپریس کرنے سے وقت بچتا ہے اور نتائج مستقل رہتے ہیں۔</p>\n<p>دونوں فائلیں ایک بیچ میں ٹول میں شامل کریں۔ ہر فائل اپنے طور پر 50KB سے نیچے کمپریس ہوتی ہے۔</p>\n<p>نتائج ZIP فائل کے طور پر ڈاؤن لوڈ کریں۔ اسے اس فولڈر میں نکالیں جہاں آپ درخواست کی دستاویزات رکھتے ہیں۔</p>\n<h2 id=\"verifying-before-submit\">جمع کرانے سے پہلے آخری چیک لسٹ</h2>\n<p>یقین کریں کہ فائل سائز آپ کے آلے پر 50KB سے نیچے پڑھتا ہے۔ 48KB سے 49.9KB کے درمیان عدد تلاش کریں۔</p>\n<p>یقین کریں کہ فارمیٹ پورٹل کے اصولوں سے میل کھاتا ہے۔ بہترین WebP فائل بھی اس پورٹل پر ناکام ہوتی ہے جو صرف JPG قبول کرتا ہے۔</p>\n<p>اگر پورٹل ابعاد طے کرتا ہے تو ان کی تصدیق کریں۔ تصویر کی خصوصیات کھولیں اور پکسل گنتی سیدھا پڑھیں۔</p>\n<h2 id=\"group-photos\">50KB پر گروپ تصویریں اور بھیڑ والی تصویریں</h2>\n<p>گروپ تصویریں 50KB پر سب سے مشکل صورت ہیں۔ ہر چہرے کو تفصیل چاہیے، اور بیس چہروں کو ایک چہرے سے بیس گنا تفصیل چاہیے ہوتی ہے۔</p>\n<p>گروپ کو جتنا ممکن ہو سخت کراپ کریں۔ خالی آسمان اور زمین ہٹا دیں تاکہ چہرے فریم بھریں اور بجٹ کا زیادہ حصہ پائیں۔</p>\n<p>قبول کریں کہ انفرادی چہرے نرم ہوں گے۔ 50KB پر گروپ تصویر تقریب کی ریکارڈ کے طور پر کام کرتی ہے، پورٹریٹ کے سیٹ کے طور پر نہیں۔</p>\n<h2 id=\"file-naming\">فائلوں کے نام اس طرح رکھیں کہ کبھی الجھیں نہیں</h2>\n<p>کمپریس شدہ فائلوں کو اکثر ٹول سے عام نام ملتے ہیں، اور عام نام غلطیاں پیدا کرتے ہیں۔ image-50kb.jpg نام کی فائل یہ نہیں بتاتی کہ یہ کس کی تصویر ہے۔</p>\n<p>نام رکھنے کی عادت بنائیں: مقصد، شخص اور سائز۔ visa-photo-ahmed-50kb.jpg جیسا نام مہینوں بعد بھی صاف ہوتا ہے اور الجھنا ناممکن ہوتا ہے۔</p>\n<p>تمام درخواستوں میں وہی نمونہ رکھیں۔ جب ہر فائل ایک ہی شکل پر چلے تو درست فائل ڈھونڈنے میں سیکنڈ لگتے ہیں۔</p>\n<h2 id=\"portal-previews\">دو بار جانچنے کے لیے پورٹل پیش نظارہ استعمال کرنا</h2>\n<p>کئی پورٹل اپ لوڈ کے بعد پیش نظارہ دکھاتے ہیں۔ اسے استعمال کریں۔ پیش نظارہ آپ کی تصویر کا پورٹل کا اپنا نظارہ ہے، اور یہ مسئلہ پکڑنے کا آخری موقع ہے۔</p>\n<p>جانچیں کہ تصویر درست طرف اوپر ہے۔ پیش نظارہ میں گھومی ہوئی تصویر کا مطلب ہے کہ پورٹل نے سمت آپ کے فون سے مختلف پڑھی ہے۔</p>\n<p>جانچیں کہ چہرہ درمیان میں ہے اور مکمل نظر آتا ہے۔ کنارے کاٹنے والا پیش نظارہ ٹھوڑی یا پیشانی کاٹ سکتا ہے۔</p>\n<p>50KB حدیں کیوں ہیں اور کمپریشن کیسے کام کرتی ہے، اس کا مکمل پس منظر <a href=\"/ur/blog/tasveer-50kb-tak-compress-karein-rehnumai/\">Compress Image to 50KB: Complete Guide</a> میں پڑھیں۔ عہد کرنے سے پہلے سائز موازنہ کرنے کے لیے <a href=\"/ur/blog/tasveer-size-50kb-vs-100kb-vs-200kb/\">50KB vs 100KB vs 200KB: Which Size to Choose?</a> دیکھیں۔ اگر آپ کا پورٹل بڑی فائل دیتا ہے تو <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">100KB کمپریسر</a> نمایاں طور پر زیادہ تفصیل رکھتا ہے۔</p>\n";

